{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/project-tiles.json
    The projects of ProjectGrid as tiles: cards (picture, featured badge, category and year, title, summary, tags, two links), compact cards in four columns, captions over the pictures, or a bento where the first project takes a big tile.
    Props (p): projects, labels, layout. *}
{var $v_projects = ($p['projects'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'cards')}
{var $v_over = (og_t(og_eq($v_layout, 'overlay')) ? true : og_eq($v_layout, 'bento'))}
{capture $c_13}
  {foreach og_l($v_projects) as $v_p}
    {var $v_i = $iterator->counter0}
    {capture $c_12}
      {capture $c_2}
        {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_p, ['title']), 'ratio' => (og_t(og_eq($v_layout, 'compact')) ? '1/1' : (og_t($v_over) ? '3/4' : '4/3')), 'className' => og_cnv([(og_t($v_over) ? 'h-full' : '')])]])|noescape}
        {if og_t(og_and([og_get($v_p, ['featured']), !(og_eq($v_layout, 'compact'))]))}
          {capture $c_1}
            {=og_text(og_get($v_labels, ['featured']))}
          {/capture}
          {=og_include('compose/Badge.latte', ['variant' => 'default', 'size' => 'default', 'class' => 'absolute left-4 top-4', 'children' => (string) $c_1])|noescape}
        {/if}
      {/capture}
      {=og_include('compose/Box.latte', ['class' => og_s((og_t($v_over) ? 'h-full' : 'relative')), 'children' => (string) $c_2])|noescape}
      {capture $c_11}
        {capture $c_3}
          {=og_text(og_tpl('{0}, {1}', [og_get($v_p, ['category']), og_get($v_p, ['year'])]))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_3])|noescape}
        {capture $c_4}
          {=og_text(og_get($v_p, ['title']))}
        {/capture}
        {=og_include('compose/Title.latte', ['as' => 3, 'size' => og_s((og_t(og_eq($v_layout, 'compact')) ? 'sm' : 'lg')), 'weight' => 'semibold', 'children' => (string) $c_4])|noescape}
        {if og_t(!(og_eq($v_layout, 'compact')))}
          {capture $c_5}
            {=og_text(og_get($v_p, ['summary']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_5])|noescape}
        {/if}
        {if og_t(og_eq($v_layout, 'cards'))}
          {capture $c_7}
            {foreach og_l(og_get($v_p, ['tags'])) as $v_k}
              {capture $c_6}
                {=og_text($v_k)}
              {/capture}
              {=og_include('compose/Badge.latte', ['variant' => 'secondary', 'size' => 'sm', 'children' => (string) $c_6])|noescape}
            {/foreach}
          {/capture}
          {=og_include('compose/Group.latte', ['gap' => '2', 'class' => 'flex-wrap', 'children' => (string) $c_7])|noescape}
          {capture $c_10}
            {capture $c_8}
              {=og_text(og_get($v_labels, ['case']))}
              {=og_include('icons/LucideIcon.latte', ['name' => 'arrow-right', 'size' => 16])|noescape}
            {/capture}
            {=og_include('blocks/menu-entry.latte', ['p' => ['href' => og_get($v_p, ['href']), 'className' => og_cnv(['inline-flex items-center gap-2 text-sm font-medium'])], 'children' => og_markup($c_8)])|noescape}
            {capture $c_9}
              {=og_text(og_get($v_labels, ['view']))}
              {=og_include('icons/LucideIcon.latte', ['name' => 'external-link', 'size' => 16])|noescape}
            {/capture}
            {=og_include('blocks/menu-entry.latte', ['p' => ['href' => og_get($v_p, ['href']), 'className' => og_cnv(['inline-flex items-center gap-2 text-sm font-medium'])], 'children' => og_markup($c_9)])|noescape}
          {/capture}
          {=og_include('compose/Group.latte', ['gap' => '4', 'class' => 'pt-2', 'children' => (string) $c_10])|noescape}
        {/if}
      {/capture}
      {=og_include('compose/Stack.latte', ['gap' => '2', 'align' => 'stretch', 'class' => og_s((og_t($v_over) ? 'absolute right-4 bottom-4 left-4 rounded bg-background p-4' : '')), 'children' => (string) $c_11])|noescape}
    {/capture}
    {=og_include('blocks/article-block.latte', ['p' => ['className' => og_cnv([og_cnv(['flex flex-col gap-4', (og_t($v_over) ? 'relative' : 'rounded bg-card inset-ring inset-ring-border p-4'), (og_t(og_and([og_eq($v_layout, 'bento'), og_eq($v_i, 0)])) ? 'sm:col-span-2 lg:row-span-2' : '')])]), 'testid' => 'item'], 'children' => og_markup($c_12)])|noescape}
  {/foreach}
{/capture}
{=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'compact')) ? 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4' : 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3')), 'attrs' => og_attrs(['data-slot', 'items']), 'children' => (string) $c_13])|noescape}
